"""Install Mary CharacterSourcebook retrieval tuning Alpha.

Edits only mary/character/sourcebook.py::CharacterSourcebook.select().
A backup is stored outside the repository in the OS temp directory.
If the resulting module does not compile, the original is restored automatically.
"""
from __future__ import annotations

from pathlib import Path
import py_compile
import shutil
import tempfile

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "mary" / "character" / "sourcebook.py"
MARKER = "# CHARACTER_RETRIEVAL_ALPHA_2026_08_31"
BACKUP_DIR = Path(tempfile.gettempdir()) / "MaryV2_patch_backups"
BACKUP = BACKUP_DIR / "sourcebook.py.pre_character_retrieval_alpha"

METHOD = '    def select(\n        self,\n        query: str,\n        *,\n        limit: int = 6,\n        max_characters: int = 4200,\n    ) -> CharacterSourceSelection:\n        """Retrieve the smallest relevant authored character evidence set.\n\n        Retrieval remains deterministic and local. A tiny Mary-domain concept\n        expansion improves semantic matching without creating another character\n        authority, embedding service, or provider dependency.\n        """\n        # CHARACTER_RETRIEVAL_ALPHA_2026_08_31\n        if not self.records:\n            return CharacterSourceSelection(\n                str(query),\n                (),\n                0,\n                self.sourcebook_hash,\n            )\n\n        raw_query = str(query or "")\n        lowered = raw_query.lower()\n        query_tokens = self._tokens(raw_query)\n\n        concept_families = (\n            (\n                {"comfort", "comforts", "console", "reassure", "upset", "grief", "sad", "cry", "hurt"},\n                {"care", "comfort", "help", "stay", "protect", "space", "tender", "upset", "hurt", "attention", "action"},\n            ),\n            (\n                {"bucko", "catchphrase", "tic", "repeating", "repeated", "saying"},\n                {"bucko", "catchphrase", "tic", "distinctive", "vocabulary", "repeat", "repetition", "humor", "phrase"},\n            ),\n            (\n                {"angry", "anger", "furious", "mad", "pissed"},\n                {"anger", "angry", "still", "neutral", "quiet", "shouting", "restraint"},\n            ),\n            (\n                {"steal", "steals", "stole", "food", "fries", "plate"},\n                {"steal", "stole", "theft", "food", "plate", "retaliation", "territorial"},\n            ),\n            (\n                {"remember", "memory", "dave", "fictional", "canon"},\n                {"remember", "memory", "fictional", "canon", "autobiographical", "history", "dave", "lived"},\n            ),\n            (\n                {"deadline", "late", "procrastinate", "procrastinating", "rush"},\n                {"deadline", "late", "lateness", "procrastination", "frantic", "focus", "work"},\n            ),\n        )\n\n        attraction_context = (\n            bool(\n                query_tokens.intersection(\n                    {\n                        "flustered",\n                        "crush",\n                        "attracted",\n                        "attraction",\n                        "beautiful",\n                        "flirt",\n                        "flirting",\n                    }\n                )\n            )\n            or "likes someone" in lowered\n            or "like someone" in lowered\n        )\n\n        expanded_tokens: set[str] = set()\n        for triggers, expansions in concept_families:\n            if query_tokens.intersection(triggers):\n                expanded_tokens.update(expansions)\n\n        if attraction_context:\n            expanded_tokens.update(\n                {\n                    "attraction",\n                    "attracted",\n                    "shy",\n                    "nervous",\n                    "flustered",\n                    "romantic",\n                    "compliment",\n                    "beautiful",\n                    "flirt",\n                    "flirting",\n                }\n            )\n\n        negative_context = any(\n            phrase in lowered\n            for phrase in (\n                "wrong",\n                "not mary",\n                "generic",\n                "bad response",\n                "avoid",\n                "never",\n                "keeps saying",\n                "too much",\n                "repeating",\n                "repeated",\n            )\n        )\n        public_context = any(\n            word in lowered\n            for word in ("stream", "audience", "public", "chat", "perform")\n        )\n\n        scored: list[tuple[float, CharacterSourceRecord]] = []\n\n        for record in self.records:\n            heading_lower = record.heading.lower()\n            body_tokens = self._tokens(\n                f"{record.heading} {record.text}"\n            )\n\n            exact_overlap = len(\n                query_tokens.intersection(body_tokens)\n            )\n            concept_overlap = len(\n                expanded_tokens.intersection(body_tokens)\n            )\n\n            related_overlap = 0\n            for query_token in query_tokens:\n                if query_token in body_tokens or len(query_token) < 5:\n                    continue\n                if any(\n                    len(body_token) >= 5\n                    and (\n                        body_token.startswith(query_token)\n                        or query_token.startswith(body_token)\n                    )\n                    for body_token in body_tokens\n                ):\n                    related_overlap += 1\n\n            lexical = 0.0\n            if query_tokens:\n                lexical = (\n                    exact_overlap\n                    + (0.65 * related_overlap)\n                    + (0.55 * concept_overlap)\n                ) / max(\n                    1.0,\n                    len(query_tokens) ** 0.5,\n                )\n\n            labels = record.evidence_labels\n            label_weight = max(\n                _LABEL_WEIGHT.get(label, 0.75)\n                for label in labels\n            )\n\n            heading_bonus = 0.0\n            for token in query_tokens:\n                if token in heading_lower:\n                    heading_bonus += 0.20\n            for token in expanded_tokens:\n                if token in heading_lower:\n                    heading_bonus += 0.10\n\n            context_bonus = 0.0\n            if negative_context and record.is_negative_example:\n                context_bonus += 0.90\n            if (\n                public_context\n                and CharacterEvidenceLabel.PUBLIC_PERFORMER in labels\n            ):\n                context_bonus += 0.50\n\n            score = (\n                lexical * label_weight\n                + heading_bonus\n                + context_bonus\n            )\n\n            # Strong authored authority gets a tiny tie-break only after\n            # relevance exists. It never creates relevance by itself.\n            if (\n                score > 0.0\n                and record.source_name\n                == "mary_character_authority_alpha.jsonl"\n            ):\n                score += 0.08\n\n            # "Comfort someone she loves" must not be hijacked by a record\n            # that only happens to contain the word "loves" in an anger rule.\n            comfort_context = bool(\n                query_tokens.intersection(\n                    {\n                        "comfort",\n                        "comforts",\n                        "console",\n                        "reassure",\n                        "grief",\n                        "sad",\n                        "cry",\n                    }\n                )\n            )\n            if (\n                comfort_context\n                and body_tokens.intersection({"anger", "angry"})\n                and not body_tokens.intersection(\n                    {\n                        "care",\n                        "comfort",\n                        "help",\n                        "stay",\n                        "protect",\n                        "tender",\n                        "upset",\n                        "hurt",\n                    }\n                )\n            ):\n                score -= 0.50\n\n            # "Likes someone and gets flustered" means attraction, not\n            # "likes an idea." Down-rank records with no attraction evidence.\n            if attraction_context and not body_tokens.intersection(\n                {\n                    "attraction",\n                    "attracted",\n                    "shy",\n                    "nervous",\n                    "flustered",\n                    "romantic",\n                    "compliment",\n                    "beautiful",\n                    "flirt",\n                    "flirting",\n                }\n            ):\n                score -= 0.70\n\n            if score > 0.0:\n                scored.append((score, record))\n\n        if not scored:\n            return CharacterSourceSelection(\n                raw_query,\n                (),\n                len(self.records),\n                self.sourcebook_hash,\n            )\n\n        scored.sort(\n            key=lambda row: (row[0], -row[1].ordinal),\n            reverse=True,\n        )\n\n        # Six is a ceiling, not a quota. Weak tail records do not get padded\n        # into TurnMind merely because room remains.\n        best_score = scored[0][0]\n        relative_floor = max(\n            0.22,\n            best_score * 0.38,\n        )\n\n        chosen: list[CharacterSourceRecord] = []\n        used = 0\n        bounded_limit = max(\n            1,\n            min(int(limit), 12),\n        )\n        character_budget = max(\n            500,\n            int(max_characters),\n        )\n\n        for score, record in scored:\n            if len(chosen) >= bounded_limit:\n                break\n            if score < relative_floor:\n                continue\n\n            cost = (\n                len(record.text)\n                + len(record.heading)\n                + 80\n            )\n            if (\n                chosen\n                and used + cost > character_budget\n            ):\n                continue\n\n            chosen.append(record)\n            used += cost\n\n        return CharacterSourceSelection(\n            raw_query,\n            tuple(chosen),\n            len(self.records),\n            self.sourcebook_hash,\n        )\n'

if not TARGET.exists():
    raise SystemExit(f"Missing target: {TARGET}")

original = TARGET.read_text(encoding="utf-8")

if MARKER in original:
    print("Retrieval Alpha is already installed.")
    raise SystemExit(0)

start_token = "    def select(\n"
end_token = "    def snapshot("

start = original.find(start_token)
if start < 0:
    raise SystemExit("Could not locate CharacterSourcebook.select(); no change made.")

end = original.find(end_token, start)
if end < 0:
    raise SystemExit("Could not locate CharacterSourcebook.snapshot(); no change made.")

BACKUP_DIR.mkdir(parents=True, exist_ok=True)
shutil.copy2(TARGET, BACKUP)

patched = original[:start] + METHOD + "\n" + original[end:]
TARGET.write_text(patched, encoding="utf-8")

try:
    py_compile.compile(str(TARGET), doraise=True)
except Exception:
    shutil.copy2(BACKUP, TARGET)
    raise

print("Installed CharacterSourcebook retrieval Alpha.")
print("Target:", TARGET)
print("Backup:", BACKUP)
print("Compile check: PASS")
